// Config is the complete configuration for a Kernel node.
// Schematic assembles this config and delivers it as a single file.
// Kernel reads the file at boot. Hot-reloadable fields (delegates,
// entitlements, rate limits, token lifetimes) can be updated by
// re-reading the file on signal; topology and TLS changes require restart.
type Config struct {
	state protoimpl.MessageState `protogen:"open.v1"`
	// cluster_name is the logical name for this cluster.
	// All nodes in the same cluster must use the same name.
	ClusterName string `protobuf:"bytes,1,opt,name=cluster_name,json=clusterName,proto3" json:"cluster_name,omitempty"`
	// listener is the gRPC bind address for the Kernel server. Default port 5000.
	Listener *host.Host `protobuf:"bytes,2,opt,name=listener,proto3" json:"listener,omitempty"`
	// members is the list of cluster member addresses for discovery (e.g. host=10.0.0.1, port=9443).
	// At least one member must be specified for the node to join the cluster.
	Members []*host.Host `protobuf:"bytes,3,rep,name=members,proto3" json:"members,omitempty"`
	// node_count is the expected number of nodes in the cluster.
	// Used for partition planning and quorum calculations.
	// Must be at least 1.
	NodeCount int32 `protobuf:"varint,4,opt,name=node_count,json=nodeCount,proto3" json:"node_count,omitempty"`
	// partition_count is the number of partitions to distribute data across.
	// More partitions enable finer-grained distribution but increase metadata overhead.
	// Default: 271 (prime number for better distribution).
	// Must be greater than 0.
	PartitionCount int32 `protobuf:"varint,5,opt,name=partition_count,json=partitionCount,proto3" json:"partition_count,omitempty"`
	// network configures cluster networking (timeouts, heartbeats, etc.).
	Network *hazelcast.NetworkConfig `protobuf:"bytes,6,opt,name=network,proto3" json:"network,omitempty"`
	// logger configures logging for the Kernel server.
	Logger *logger.LoggerConfig `protobuf:"bytes,7,opt,name=logger,proto3" json:"logger,omitempty"`
	// persistence_dir is the directory where DB dumps and redo logs are stored.
	// Default: "data/kernel".
	PersistenceDir string `protobuf:"bytes,8,opt,name=persistence_dir,json=persistenceDir,proto3" json:"persistence_dir,omitempty"`
	// persistence_format configures the serialization format for redo logs and dumps.
	// Default: OUTPUT_FORMAT_PROTO_WIRE (binary protobuf).
	PersistenceFormat outputformat.OutputFormat `protobuf:"varint,9,opt,name=persistence_format,json=persistenceFormat,proto3,enum=outputformat.OutputFormat" json:"persistence_format,omitempty"`
	// hazelcast_listener is the bind address for Hazelcast cluster communication. Default port 5001.
	HazelcastListener *host.Host `protobuf:"bytes,10,opt,name=hazelcast_listener,json=hazelcastListener,proto3" json:"hazelcast_listener,omitempty"`
	// tls is the node's X.509 certificate and private key, used for
	// gRPC server TLS and Hazelcast mTLS.
	Tls *x509.X509CertChain `protobuf:"bytes,11,opt,name=tls,proto3" json:"tls,omitempty"`
	// cluster_ca holds the cluster root CA certificate(s) for populating
	// Ca.ca_certs on startup and for Hazelcast mTLS trust.
	// These are the trust anchors for all cert chain validation in the cluster.
	ClusterCa []*x509.X509Cert `protobuf:"bytes,12,rep,name=cluster_ca,json=clusterCa,proto3" json:"cluster_ca,omitempty"`
	// signing_ca is the node's intermediate CA chain issued by schematic,
	// used by X509Mint to sign service certificates. The chain is:
	//
	//	node intermediate (pathlen:0) → cluster intermediate → root CA.
	//
	// The private key is included (for signing) but never leaves the node.
	SigningCa *x509.X509CertChain `protobuf:"bytes,13,opt,name=signing_ca,json=signingCa,proto3" json:"signing_ca,omitempty"`
	// trusted_cas lists the trusted CA certificates for TLS verification.
	TrustedCas []*x509.X509Cert `protobuf:"bytes,14,rep,name=trusted_cas,json=trustedCas,proto3" json:"trusted_cas,omitempty"`
	// rate_limit configures rate limiting for unary read RPCs to detect polling.
	RateLimit *hazelcast.RateLimitConfig `protobuf:"bytes,15,opt,name=rate_limit,json=rateLimit,proto3" json:"rate_limit,omitempty"`
	// configs holds per-service configurations. On each config load,
	// each entry is written to the corresponding service config state boundary.
	Configs *services_config.Services `protobuf:"bytes,16,opt,name=configs,proto3" json:"configs,omitempty"`
	// delegates hold credentials for services that can request tokens.
	// Each delegate identifies a service and its authorized target services.
	Delegates []*Delegate `protobuf:"bytes,17,rep,name=delegates,proto3" json:"delegates,omitempty"`
	// fqdn is the fully qualified domain name for this cluster
	// (e.g. "api.example.com"). Published to Identity state for
	// services like letsencrypt. No default — must be set for production.
	Fqdn string `protobuf:"bytes,20,opt,name=fqdn,proto3" json:"fqdn,omitempty"`
	// issuer is the full issuer URL for tokens minted by this cluster.
	// For local development, computed as https://<fqdn>:<port> (port omitted if 443).
	// For production behind a load balancer, set explicitly (e.g. "https://api.example.com").
	Issuer string `protobuf:"bytes,21,opt,name=issuer,proto3" json:"issuer,omitempty"`
	// key_rotation_interval_seconds is how often the exchanger rotates
	// its own signing keys. Default: 24 hours.
	KeyRotationIntervalSeconds int64 `protobuf:"varint,22,opt,name=key_rotation_interval_seconds,json=keyRotationIntervalSeconds,proto3" json:"key_rotation_interval_seconds,omitempty"`
	// default_token_expiry_seconds is the default lifetime for issued
	// access tokens when the request does not specify an expiry. Default: 1 hour.
	DefaultTokenExpirySeconds int64 `protobuf:"varint,23,opt,name=default_token_expiry_seconds,json=defaultTokenExpirySeconds,proto3" json:"default_token_expiry_seconds,omitempty"`
	// ca_cert_lifetime_seconds is the lifetime for node CA certificates.
	// Default: 31536000 (1 year). Node CA certs are regenerated on restart.
	CaCertLifetimeSeconds int64 `protobuf:"varint,24,opt,name=ca_cert_lifetime_seconds,json=caCertLifetimeSeconds,proto3" json:"ca_cert_lifetime_seconds,omitempty"`
	// access_token_lifetime_seconds is the default lifetime for user access tokens
	// minted via MintToken. Default: 900 (15 minutes).
	AccessTokenLifetimeSeconds int64 `protobuf:"varint,25,opt,name=access_token_lifetime_seconds,json=accessTokenLifetimeSeconds,proto3" json:"access_token_lifetime_seconds,omitempty"`
	// refresh_token_lifetime_seconds is the default lifetime for user refresh tokens
	// minted via MintToken. Default: 86400 (24 hours).
	RefreshTokenLifetimeSeconds int64 `protobuf:"varint,26,opt,name=refresh_token_lifetime_seconds,json=refreshTokenLifetimeSeconds,proto3" json:"refresh_token_lifetime_seconds,omitempty"`
	// tls_cert_lifetime_seconds is the lifetime for auto-TLS service certificates.
	// Kernel sends a renewal request at half-life. Default: 86400 (24 hours).
	TlsCertLifetimeSeconds int64 `protobuf:"varint,27,opt,name=tls_cert_lifetime_seconds,json=tlsCertLifetimeSeconds,proto3" json:"tls_cert_lifetime_seconds,omitempty"`
	// max_token_lifetime_seconds is the maximum lifetime kernel will allow for
	// any minted token. Requests with exp beyond now + this value are rejected.
	// Delegates control their own exp policy within this ceiling.
	// Default: 2592000 (30 days).
	MaxTokenLifetimeSeconds int64 `protobuf:"varint,28,opt,name=max_token_lifetime_seconds,json=maxTokenLifetimeSeconds,proto3" json:"max_token_lifetime_seconds,omitempty"`
	// offline_token_lifetime_seconds is the default lifetime for Offline Tokens
	// (OT) — the long-lived, identity-only tokens persisted on disk by the
	// schematic daemon and renewed before half-life. Months, not hours.
	// Default: 7776000 (90 days). Exempt from max_token_lifetime_seconds, which
	// caps short-lived access/service tokens.
	OfflineTokenLifetimeSeconds int64 `protobuf:"varint,31,opt,name=offline_token_lifetime_seconds,json=offlineTokenLifetimeSeconds,proto3" json:"offline_token_lifetime_seconds,omitempty"`
	// root_cred_pairs are the bootstrap admin credentials, rendered into this
	// config by the operator from operator.yaml. Each is an ordinary C2S CredPair
	// owned by the root namespace; kernel installs them into the root namespace's
	// TenantConfig at boot (granting full entitlements) so a holder can sign a
	// proof, exchange it via MintClientToken, and provision tenants/projects via
	// TenantAdmin. Only the public half is carried here.
	RootCredPairs []*credentials.CredPair `protobuf:"bytes,32,rep,name=root_cred_pairs,json=rootCredPairs,proto3" json:"root_cred_pairs,omitempty"`
	// spiffe_trust_domain is the SPIFFE URI authority: a globally unique instance
	// name for this autonomous-system instance (need not be a DNS domain). It must
	// not contain '/', a scheme, query, or fragment, and carries no path. Service
	// identity is built by the generated sys/spiffe helper as:
	//
	//	spiffe://<spiffe_trust_domain>/system/<location_path...>/services/<service_label>
	//
	// If empty, SPIFFE IDs are not set on issued tokens or X509 URI SANs. Kernel
	// copies this (with location_path) into the runtime grpcconfig.Config it seeds
	// into ServiceConfigState, so every service shares one trust domain.
	SpiffeTrustDomain string `protobuf:"bytes,33,opt,name=spiffe_trust_domain,json=spiffeTrustDomain,proto3" json:"spiffe_trust_domain,omitempty"`
	// location_path is this deployment's topology path under /system — opaque,
	// tag-delimited, slash-separated segments, arity not fixed (e.g.
	// "aws/123456789012/us-east-1a/cluster-7/team-a"). Segments follow the SPIFFE
	// segment grammar and must not be reserved tags. Supplied by the operator from
	// runtime config (where the cluster runs); it is not a token claim. May be
	// empty (no topology tiers).
	LocationPath string `protobuf:"bytes,34,opt,name=location_path,json=locationPath,proto3" json:"location_path,omitempty"`
	// health_probe_port is the plaintext gRPC port for k8s health probes.
	// Kernel's hand-written bootstrap bypasses the generated ServiceManager,
	// so this field must be on Kernel.Config (not only on Grpcconfig.Config).
	// Default matches the platform-wide health probe port.
	HealthProbePort int32  `protobuf:"varint,35,opt,name=health_probe_port,json=healthProbePort,proto3" json:"health_probe_port,omitempty"`
	TraceId         string `protobuf:"bytes,200,opt,name=trace_id,json=traceId,proto3" json:"trace_id,omitempty"`
	Noop            bool   `protobuf:"varint,201,opt,name=noop,proto3" json:"noop,omitempty"`
	unknownFields   protoimpl.UnknownFields
	sizeCache       protoimpl.SizeCache
}

